// TYPES
// ============================================================================

export type ChannelType = 'in_app' | 'slack' | 'email' | 'sms' | 'webhook';
export type AlertSeverity = 'info' | 'warning' | 'critical';

export interface ChannelConfig {
  id: string;
  type: ChannelType;
  name: string;
  enabled: boolean;
  /** Minimum severity to trigger this channel */
  minSeverity: AlertSeverity;
  /** Rate limit: max alerts per hour for this channel */
  maxPerHour: number;
  /** Retry count on failure */
  retryCount: number;
  /** Retry delay base in ms (exponential backoff) */
  retryDelayMs: number;
  /** Channel-specific configuration */
  settings: Record<string, string>;
}

export interface NotificationPayload {
  title: string;
  content: string;
  severity: AlertSeverity;
  source: string;
  timestamp: number;
  metadata?: Record<string, unknown>;
}

export interface DeliveryResult {
  channelId: string;
  channelType: ChannelType;
  channelName: string;
  success: boolean;
  attempts: number;
  latencyMs: number;
  error?: string;
  timestamp: number;
}

export interface ChannelStats {
  channelId: string;
  channelType: ChannelType;
  channelName: string;
  enabled: boolean;
  totalSent: number;
  totalFailed: number;
  totalRetried: number;
  sentThisHour: number;
  lastDelivery: number | null;
  lastError: string | null;
  avgLatencyMs: number;
}

// ============================================================================
// SEVERITY HELPERS
// ============================================================================

