export type ScheduleStatus = 'pending' | 'active' | 'completed' | 'cancelled' | 'failed' | 'paused';
export type ScheduleRecurrence = 'once' | 'daily' | 'weekly' | 'biweekly' | 'monthly';

export interface PreRolloutCheck {
  name: string;
  description: string;
  check: () => Promise<{ passed: boolean; message: string }>;
}

export interface ScheduledRollout {
  id: string;
  /** Human-readable name */
  name: string;
  /** Description of what this rollout deploys */
  description: string;
  /** Scheduled start time (UTC ms) */
  scheduledAt: number;
  /** When the schedule was created */
  createdAt: number;
  /** When the rollout actually started (null if not yet) */
  startedAt: number | null;
  /** When the rollout completed/cancelled/failed */
  endedAt: number | null;
  /** Current status */
  status: ScheduleStatus;
  /** Recurrence pattern */
  recurrence: ScheduleRecurrence;
  /** Next occurrence for recurring schedules */
  nextOccurrence: number | null;
  /** Custom rollout config overrides */
  rolloutConfigOverrides: Partial<RolloutConfig>;
  /** Pre-rollout checks to run before starting */
  preChecks: string[];
  /** Whether to auto-advance through stages */
  autoAdvance: boolean;
  /** Maximum duration before auto-cancel (ms) */
  maxDurationMs: number;
  /** Tags for filtering */
  tags: string[];
  /** Created by (admin ID) */
  createdBy: string;
  /** Cancellation reason if cancelled */
  cancelReason: string | null;
  /** Failure reason if failed */
  failureReason: string | null;
  /** Audit log */
  auditLog: ScheduleAuditEntry[];
}

export interface ScheduleAuditEntry {
  timestamp: number;
  action: string;
  actor: string;
  details: string;
}

export interface CreateScheduleInput {
  name: string;
  description: string;
  scheduledAt: number;
  recurrence?: ScheduleRecurrence;
  rolloutConfigOverrides?: Partial<RolloutConfig>;
  preChecks?: string[];
  autoAdvance?: boolean;
  maxDurationMs?: number;
  tags?: string[];
  createdBy?: string;
}

// ─── Pre-Rollout Checks Registry ─────────────────────────────────

const preCheckRegistry: Map<string, PreRolloutCheck> = new Map();

// Register default pre-rollout checks
preCheckRegistry.set('system_health', {
  name: 'System Health',
  description: 'Verify system is healthy before rollout',
  check: async () => {
    // Check if there's no active rollout
    const controller = getRolloutController();
    const state = controller.getState();
    if (state.status === 'rolling_out') {
      return { passed: false, message: 'Another rollout is already in progress' };
    }
    return { passed: true, message: 'System is healthy, no active rollout' };
  },
});

preCheckRegistry.set('error_rate', {
  name: 'Error Rate Check',
  description: 'Ensure current error rate is below threshold',
  check: async () => {
    const controller = getRolloutController();
    const metrics = controller.getMetrics();
    const errorRate = metrics.requestSummary.total > 0
      ? metrics.requestSummary.errors / metrics.requestSummary.total
      : 0;
    if (errorRate > 0.05) {
      return { passed: false, message: `Error rate ${(errorRate * 100).toFixed(1)}% exceeds 5% threshold` };
    }

