updateConfig(updates: Partial<RolloutConfig>): RolloutConfig {
  this.config = { ...this.config, ...updates };
  if (updates.rolloutPercentage !== undefined) {
    this.state.rolloutPercentage = updates.rolloutPercentage;
  }
  if (updates.shadowMode !== undefined || updates.logAllRequests !== undefined) {
    this.addEvent('manual_action', `Config updated: shadow=${this.config.shadowMode}, logAll=${this.config.logAllRequests}`);
  }
  return { ...this.config };
}

getConfig(): RolloutConfig {
  return { ...this.config };
}

// ─── State & History ─────────────────────────────────────────────────

getState(): RolloutState {
  return { ...this.state };
}

getEvents(limit = 50): RolloutEvent[] {
  return this.events.slice(-limit);
}

getRequestLogs(limit = 100): RequestLog[] {
  return this.requestLogs.slice(-limit);
}

getHealthHistory(limit = 50): HealthCheckResult[] {
  return this.healthHistory.slice(-limit);
}

getMetrics(): {
  state: RolloutState;
  config: RolloutConfig;
  healthHistory: HealthCheckResult[];
  recentEvents: RolloutEvent[];
  requestSummary: {
    total: number;
    rolledOut: number;
    shadow: number;
    errors: number;
    errorRate: number;
    avgLatencyMs: number;
  };
} {
  const recent = this.recentRequests;
  const latencies = recent.map(r => r.latencyMs);
  return {
    state: { ...this.state },
    config: { ...this.config },
    healthHistory: this.healthHistory.slice(-10),
    recentEvents: this.events.slice(-20),
    requestSummary: {
      total: this.state.totalRequests,
      rolledOut: this.state.rolledOutRequests,
      shadow: this.state.shadowRequests,
      errors: this.state.errors,
      errorRate: this.state.totalRequests > 0 ? this.state.errors / this.state.totalRequests : 0,
      avgLatencyMs: latencies.length > 0 ? latencies.reduce((s, l) => s + l, 0) / latencies.length : 0,
    },
  };
}

// ─── Helpers ─────────────────────────────────────────────────────────

private addEvent(type: RolloutEvent['type'], message: string, metadata?: Record<string, unknown>): void {
  this.events.push({
    id: `evt_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
    timestamp: Date.now(),
    type,
    stage: this.state.currentStage,
    percentage: this.state.rolloutPercentage,
    message,
    metadata,
  });
  if (this.events.length > 500) {
    this.events.splice(0, this.events.length - 500);
  }
}

reset(): void {
  this.stopHealthChecks();
  this.state = {
    status: 'idle',
    currentStage: 'disabled',
    rolloutPercentage: 0,
    stageStartedAt: null,
    totalRequests: 0,

