88	  configOverrides?: Partial<AutoRestoreConfig>
89	): Promise<RestoreResult> {
90	  const config = { ..._config, ...configOverrides };
91	  _restoreAttempts++;
92	
93	  const noopResult = (message: string): RestoreResult => ({
94	    restored: false,
95	    status: 'idle',
96	    message,
97	    restoredAt: Date.now(),
98	  });
99	
100	  // Check if enabled
101	  if (!config.enabled) {
102	    generalLog.info({}, '[AutoRestore] Auto-restore is disabled');
103	    _lastRestoreResult = noopResult('Auto-restore is disabled');
104	    return _lastRestoreResult;
105	  }
106	
107	  try {
108	    // Load the most recent rollout state from DB
109	    const persisted = await loadRolloutState();
110	
111	    if (!persisted) {
112	      generalLog.info({}, '[AutoRestore] No persisted rollout state found');
113	      _lastRestoreResult = noopResult('No persisted rollout state found');
114	      return _lastRestoreResult;
115	    }
116	
117	    generalLog.info({}, `[AutoRestore] Found persisted state: status=${persisted.status}, stage=${persisted.currentStage}, pct=${persisted.percentage}%`);
118	
119	    // Check if the state is restorable (active rollout)
120	    const isActive = persisted.status === 'rolling_out' || persisted.status === 'paused';
121	    if (!isActive) {
122	      generalLog.info({}, `[AutoRestore] Persisted state is ${persisted.status} — no restoration needed`);
123	      _lastRestoreResult = noopResult(`Last rollout was ${persisted.status} — no active rollout to restore`);
124	      return _lastRestoreResult;
125	    }
126	
127	    // Check age limit
128	    const stateAge = Date.now() - (persisted.startedAt || 0);
129	    if (stateAge > config.maxStateAgeMs) {
130	      const ageHours = Math.round(stateAge / (60 * 60 * 1000));
131	      generalLog.warn({}, `[AutoRestore] Persisted state is ${ageHours}h old — exceeds max age of ${config.maxStateAgeMs / (60 * 60 * 1000)}h`);
132	      _lastRestoreResult = noopResult(`Persisted rollout is ${ageHours}h old — too stale to restore (max: ${config.maxStateAgeMs / (60 * 60 * 1000)}h)`);
133	      return _lastRestoreResult;
134	    }
135	
136	    // Restore to the controller
137	    const controller = getRolloutController();
138	    const currentState = controller.getState();
139	
140	    // Only restore if controller is idle (don't overwrite an active rollout)
141	    if (currentState.status !== 'idle') {
142	      generalLog.warn({}, `[AutoRestore] Controller is already in ${currentState.status} state — skipping restore`);
143	      _lastRestoreResult = noopResult(`Controller already in ${currentState.status} state`);
144	      return _lastRestoreResult;
145	    }
146	
147	    // Start the rollout in the controller, then adjust to the persisted state
148	    controller.startRollout();
149	
150	    // Set the percentage to match persisted state
151	    const stageName = STAGE_INDEX_TO_NAME[persisted.currentStage] || 'canary';
152	    controller.setPercentage(persisted.percentage);
153	
154	    // Update config to match persisted config
155	    if (persisted.config && typeof persisted.config === 'object') {
156	      controller.updateConfig({
157	        shadowMode: persisted.shadowMode,
158	        logAllRequests: persisted.logAllRequests,
159	        ...persisted.config,
160	      });
161	    }
162	
163	    // If restoreAsPaused, pause the rollout for safety
164	    if (config.restoreAsPaused) {
165	      controller.pauseRollout();
166	      generalLog.info({}, `[AutoRestore] Rollout restored as PAUSED at ${persisted.percentage}% — admin must resume`);
167	    } else {
168	      generalLog.info({}, `[AutoRestore] Rollout restored as ACTIVE at ${persisted.percentage}%`);
169	    }
170	
171	    // Record the restore event in the audit log
172	    const rolloutId = getActiveRolloutId() || persisted.id;
173	    try {
174	      await recordRolloutEvent({
175	        rolloutId,
176	        eventType: 'server_restart_restore',
177	        stage: persisted.currentStage,
178	        percentage: persisted.percentage,
179	        details: {
180	          restoredAs: config.restoreAsPaused ? 'paused' : 'rolling_out',
181	          previousStatus: persisted.status,
182	          stateAgeMs: stateAge,
183	          attemptNumber: _restoreAttempts,
184	        },
185	        timestamp: Date.now(),
186	      });
187	    } catch (err) {
188	      generalLog.warn({}, '[AutoRestore] Failed to record restore event:', err);
189	    }
190	
191	    // Send notification about the restoration
192	    if (config.notifyOnRestore) {
193	      try {
194	        const notifier = getMultiChannelNotifier();
195	        await notifier.dispatch({
196	          title: `Rollout Auto-Restored on Server Restart`,
197	          content: [
198	            `A previously active rollout has been restored after a server restart.`,
199	            ``,
200	            `**Status:** ${config.restoreAsPaused ? 'Paused (awaiting admin resume)' : 'Active'}`,
201	            `**Stage:** ${stageName} (${persisted.percentage}%)`,
202	            `**Original Start:** ${persisted.startedAt ? new Date(persisted.startedAt).toISOString() : 'unknown'}`,
203	            `**State Age:** ${Math.round(stateAge / 60000)} minutes`,
204	            ``,
205	            config.restoreAsPaused
206	              ? `The rollout is paused for safety. Please verify system health and resume from the Deployment Dashboard.`
207	              : `The rollout is active and will continue health checks automatically.`,
208	          ].join('\n'),
209	          severity: 'warning',
210	          source: 'rollout-auto-restore',
211	          timestamp: Date.now(),
212	          metadata: {
213	            rolloutId,
214	            stage: stageName,
215	            percentage: persisted.percentage,
216	            restoredAs: config.restoreAsPaused ? 'paused' : 'rolling_out',
217	          },
218	        });
219	      } catch (err) {
220	        generalLog.warn({}, '[AutoRestore] Failed to send restore notification:', err);
221	      }
222	    }
223	
224	    const result: RestoreResult = {
225	      restored: true,
226	      status: config.restoreAsPaused ? 'paused' : 'rolling_out',
227	      stage: stageName,
228	      percentage: persisted.percentage,
