  try {
    // Load the most recent rollout state from DB
    const persisted = await loadRolloutState();

    if (!persisted) {
      generalLog.info({}, '[AutoRestore] No persisted rollout state found');
      _lastRestoreResult = noopResult('No persisted rollout state found');
      return _lastRestoreResult;
    }

    generalLog.info({}, `[AutoRestore] Found persisted state: status=${persisted.status}, stage=${persisted.currentStage}, pct=${persisted.percentage}%`);

    // Check if the state is restorable (active rollout)
    const isActive = persisted.status === 'rolling_out' || persisted.status === 'paused';
    if (!isActive) {
      generalLog.info({}, `[AutoRestore] Persisted state is ${persisted.status} — no restoration needed`);
      _lastRestoreResult = noopResult(`Last rollout was ${persisted.status} — no active rollout to restore`);
      return _lastRestoreResult;
    }

    // Check age limit
    const stateAge = Date.now() - (persisted.startedAt || 0);
    if (stateAge > config.maxStateAgeMs) {
      const ageHours = Math.round(stateAge / (60 * 60 * 1000));
      generalLog.warn({}, `[AutoRestore] Persisted state is ${ageHours}h old — exceeds max age of ${config.maxStateAgeMs / (60 * 60 * 1000)}h`);
      _lastRestoreResult = noopResult(`Persisted rollout is ${ageHours}h old — too stale to restore (max: ${config.maxStateAgeMs / (60 * 60 * 1000)}h)`);
      return _lastRestoreResult;
    }

    // Restore to the controller
    const controller = getRolloutController();
    const currentState = controller.getState();

    // Only restore if controller is idle (don't overwrite an active rollout)
    if (currentState.status !== 'idle') {
      generalLog.warn({}, `[AutoRestore] Controller is already in ${currentState.status} state — skipping restore`);
      _lastRestoreResult = noopResult(`Controller already in ${currentState.status} state`);
      return _lastRestoreResult;
    }

    // Start the rollout in the controller, then adjust to the persisted state
    controller.startRollout();

    // Set the percentage to match persisted state
    const stageName = STAGE_INDEX_TO_NAME[persisted.currentStage] || 'canary';
    controller.setPercentage(persisted.percentage);

    // Update config to match persisted config
    if (persisted.config && typeof persisted.config === 'object') {
      controller.updateConfig({
        shadowMode: persisted.shadowMode,
        logAllRequests: persisted.logAllRequests,
        ...persisted.config,
      });
    }

    // If restoreAsPaused, pause the rollout for safety
    if (config.restoreAsPaused) {
      controller.pauseRollout();
      generalLog.info({}, `[AutoRestore] Rollout restored as PAUSED at ${persisted.percentage}% — admin must resume`);
    } else {
      generalLog.info({}, `[AutoRestore] Rollout restored as ACTIVE at ${persisted.percentage}%`);
    }

    // Record the restore event in the audit log
    const rolloutId = getActiveRolloutId() || persisted.id;
    try {
      await recordRolloutEvent({
        rolloutId,
        eventType: 'server_restart_restore',
        stage: persisted.currentStage,
        percentage: persisted.percentage,
        details: {
          restoredAs: config.restoreAsPaused ? 'paused' : 'rolling_out',
          previousStatus: persisted.status,
          stateAgeMs: stateAge,
          attemptNumber: _restoreAttempts,
        },
        timestamp: Date.now(),
      });
    } catch (err) {
      generalLog.warn({}, '[AutoRestore] Failed to record restore event:', err);
    }

    // Send notification about the restoration
    if (config.notifyOnRestore) {
      try {
        const notifier = getMultiChannelNotifier();
        await notifier.dispatch({
          title: `Rollout Auto-Restored on Server Restart`,
          content: [
            `A previously active rollout has been restored after a server restart.`,
            ``,
            `**Status:** ${config.restoreAsPaused ? 'Paused (awaiting admin resume)' : 'Active'}`,
            `**Stage:** ${stageName} (${persisted.percentage}%)`,
            `**Original Start:** ${persisted.startedAt ? new Date(persisted.startedAt).toISOString() : 'unknown'}`,
            `**State Age:** ${Math.round(stateAge / 60000)} minutes`,
            ``,
            config.restoreAsPaused
              ? `The rollout is paused for safety. Please verify system health and resume from the Deployment Dashboard.`
              : `The rollout is active and will continue health checks automatically.`,
          ].join('\n'),
          severity: 'warning',
          source: 'rollout-auto-restore',
          timestamp: Date.now(),
          metadata: {
            rolloutId,
            stage: stageName,
            percentage: persisted.percentage,
            restoredAs: config.restoreAsPaused ? 'paused' : 'rolling_out',
          },
        });
      } catch (err) {
        generalLog.warn({}, '[AutoRestore] Failed to send restore notification:', err);
      }
    }

    const result: RestoreResult = {
      restored: true,
      status: config.restoreAsPaused ? 'paused' : 'rolling_out',
      stage: stageName,
      percentage: persisted.percentage,
      message: `Rollout restored from DB: ${stageName} at ${persisted.percentage}% (${config.restoreAsPaused ? 'paused' : 'active'})`,
      previousState: {
        status: persisted.status,
        stage: persisted.currentStage,
        percentage: persisted.percentage,
        startedAt: persisted.startedAt,
      },
      restoredAt: Date.now(),
    };

    _lastRestoreResult = result;
    return result;

  } catch (err: any) {
    const errorMsg = err?.message || 'Unknown error';
    generalLog.error({}, `[AutoRestore] Failed to restore rollout state: ${errorMsg}`);
    _lastRestoreResult = noopResult(`Restore failed: ${errorMsg}`);
    return _lastRestoreResult;
  }
}

