export async function saveRolloutState(snapshot: RolloutStateSnapshot): Promise<number> {
  const now = Date.now();

  const db = await getDb();

  if (_activeRolloutId && (snapshot.status === 'rolling_out' || snapshot.status === 'paused')) {
    // Update existing active rollout
    await db.update(rolloutState)
      .set({
        status: snapshot.status,
        currentStage: snapshot.currentStage,
        percentage: snapshot.percentage,
        shadowMode: snapshot.shadowMode ? 1 : 0,
        logAllRequests: snapshot.logAllRequests ? 1 : 0,
        totalRequests: snapshot.totalRequests,
        newVersionRequests: snapshot.newVersionRequests,
        healthChecksPassed: snapshot.healthChecksPassed,
        healthChecksFailed: snapshot.healthChecksFailed,
        consecutiveFailures: snapshot.consecutiveFailures,
        configJson: snapshot.config,
        startedAt: snapshot.startedAt,
        completedAt: snapshot.completedAt,
        updatedAt: now,
      })
      .where(eq(rolloutState.id, _activeRolloutId));
    return _activeRolloutId;
  }

  // Create new rollout state row
  const [inserted] = await db.insert(rolloutState).values({
    status: snapshot.status,
    currentStage: snapshot.currentStage,
    percentage: snapshot.percentage,
    shadowMode: snapshot.shadowMode ? 1 : 0,
    logAllRequests: snapshot.logAllRequests ? 1 : 0,
    totalRequests: snapshot.totalRequests,
    newVersionRequests: snapshot.newVersionRequests,
    healthChecksPassed: snapshot.healthChecksPassed,
    healthChecksFailed: snapshot.healthChecksFailed,
    consecutiveFailures: snapshot.consecutiveFailures,
    configJson: snapshot.config,
    startedAt: snapshot.startedAt,
    completedAt: snapshot.completedAt,
    createdAt: now,
    updatedAt: now,
  }).returning({ id: rolloutState.id });

  const newId = Number(inserted.id);

  // Track active rollout for updates
  if (snapshot.status === 'rolling_out' || snapshot.status === 'paused') {
    _activeRolloutId = newId;
  } else {
    _activeRolloutId = null;
  }

  return newId;
}

