/**
 * Load the most recent rollout state from the database.
 * Returns null if no state exists.
 */
export async function loadRolloutState(): Promise<(RolloutStateSnapshot & { id: number }) | null> {
  const db = await getDb();
  const rows = await db.select()
    .from(rolloutState)
    .orderBy(desc(rolloutState.updatedAt))
    .limit(1);

  if (rows.length === 0) return null;

  const row = rows[0];

  // Track active rollout for future updates
  if (row.status === 'rolling_out' || row.status === 'paused') {
    _activeRolloutId = row.id;
  }

  return {
    id: row.id,
    status: row.status,
    currentStage: row.currentStage,
    percentage: row.percentage,
    shadowMode: row.shadowMode === 1,
    logAllRequests: row.logAllRequests === 1,
    totalRequests: row.totalRequests,
    newVersionRequests: row.newVersionRequests,
    healthChecksPassed: row.healthChecksPassed,
    healthChecksFailed: row.healthChecksFailed,
    consecutiveFailures: row.consecutiveFailures,
    config: (row.configJson as Record<string, any>) || {},
    startedAt: row.startedAt,
    completedAt: row.completedAt,
  };
}

