/**
 * Rollout Auto-Restore
 * 
 * Loads persisted rollout state from the database on server startup and
 * restores any in-progress rollout to the ProductionRolloutController.
 * 
 * Behavior:
 * - On startup, checks for the most recent rollout state in DB
 * - If an active rollout (rolling_out or paused) is found, restores it
 * - Completed/rolled-back rollouts are logged but not restored
 * - Records a 'server_restart_restore' event in the audit log
 * - Integrates with the multi-channel notifier to alert on restoration
 * 
 * Safety:
 * - Restored rollouts start in paused state (not auto-advancing)
 * - Admin must explicitly resume after verifying system health
 * - If restoration fails, the controller stays in idle state
 */

import { generalLog } from '../_core/logger';
import { loadRolloutState, recordRolloutEvent, saveRolloutState, getActiveRolloutId } from './rollout-persistence';
import { getRolloutController } from './production-rollout-controller';
import type { RolloutStage } from './production-rollout-controller';
import { getMultiChannelNotifier } from './multi-channel-notifier';

// ─── Types ──────────────────────────────────────────────────────────────────

export interface RestoreResult {
  restored: boolean;
  status: string;
  stage?: string;
  percentage?: number;
  message: string;
  previousState?: {
    status: string;
    stage: number;
    percentage: number;
    startedAt: number | null;
  };
  restoredAt: number;
}

export interface AutoRestoreConfig {
  /** Whether auto-restore is enabled */
  enabled: boolean;
  /** Restore as paused (safer) or resume rolling_out */
  restoreAsPaused: boolean;
  /** Send notification on restore */
  notifyOnRestore: boolean;
  /** Maximum age of rollout state to restore (ms). Default: 24 hours */
  maxStateAgeMs: number;
  /** Log level for restore events */
  logLevel: 'info' | 'warn' | 'debug';
}

const DEFAULT_CONFIG: AutoRestoreConfig = {
  enabled: true,
  restoreAsPaused: true, // Safer: admin must explicitly resume
  notifyOnRestore: true,
  maxStateAgeMs: 24 * 60 * 60 * 1000, // 24 hours
  logLevel: 'info',
};

// ─── Stage Mapping ──────────────────────────────────────────────────────────

const STAGE_INDEX_TO_NAME: Record<number, RolloutStage> = {
  0: 'disabled',
  1: 'canary',
  2: 'partial_25',
  3: 'partial_50',
  4: 'partial_75',
  5: 'full',
};

// ─── Auto-Restore Logic ─────────────────────────────────────────────────────

let _config: AutoRestoreConfig = { ...DEFAULT_CONFIG };
let _lastRestoreResult: RestoreResult | null = null;
let _restoreAttempts = 0;

/**
 * Attempt to restore rollout state from the database.
 * Called during server startup.
 * 
