329	  runHealthCheck(): HealthCheckResult {
330	    const now = Date.now();
331	    const windowMs = 300_000; // 5 min window
332	    const recent = this.recentRequests.filter(r => r.timestamp > now - windowMs);
333	
334	    const requestCount = recent.length;
335	    const successCount = recent.filter(r => r.success).length;
336	    const failureCount = requestCount - successCount;
337	    const errorRate = requestCount > 0 ? failureCount / requestCount : 0;
338	    const latencies = recent.map(r => r.latencyMs).sort((a, b) => a - b);
339	    const avgLatencyMs = latencies.length > 0 ? latencies.reduce((s, l) => s + l, 0) / latencies.length : 0;
340	    const p95LatencyMs = latencies.length > 0 ? latencies[Math.floor(latencies.length * 0.95)] : 0;
341	
342	    const passed = errorRate <= this.config.errorRateThreshold &&
343	                   avgLatencyMs <= this.config.latencyThresholdMs;
344	
345	    const details = passed
346	      ? `Health OK: errorRate=${(errorRate * 100).toFixed(1)}%, avgLatency=${avgLatencyMs.toFixed(0)}ms, p95=${p95LatencyMs.toFixed(0)}ms (${requestCount} requests)`
347	      : `Health FAILED: errorRate=${(errorRate * 100).toFixed(1)}% (threshold: ${(this.config.errorRateThreshold * 100).toFixed(1)}%), avgLatency=${avgLatencyMs.toFixed(0)}ms (threshold: ${this.config.latencyThresholdMs}ms)`;
348	
349	    const result: HealthCheckResult = {
350	      timestamp: now,
351	      stage: this.state.currentStage,
352	      percentage: this.state.rolloutPercentage,
353	      passed,
354	      metrics: { errorRate, avgLatencyMs, p95LatencyMs, requestCount, successCount, failureCount },
355	      details,
356	    };
357	
358	    this.healthHistory.push(result);
359	    if (this.healthHistory.length > 200) {
360	      this.healthHistory.splice(0, this.healthHistory.length - 200);
361	    }
362	
363	    this.state.lastHealthCheck = result;
364	    this.addEvent('health_check', details, { passed, errorRate, avgLatencyMs, p95LatencyMs });
365	
