runHealthCheck(): HealthCheckResult {
  const now = Date.now();
  const windowMs = 300_000; // 5 min window
  const recent = this.recentRequests.filter(r => r.timestamp > now - windowMs);

  const requestCount = recent.length;
  const successCount = recent.filter(r => r.success).length;
  const failureCount = requestCount - successCount;
  const errorRate = requestCount > 0 ? failureCount / requestCount : 0;
  const latencies = recent.map(r => r.latencyMs).sort((a, b) => a - b);
  const avgLatencyMs = latencies.length > 0 ? latencies.reduce((s, l) => s + l, 0) / latencies.length : 0;
  const p95LatencyMs = latencies.length > 0 ? latencies[Math.floor(latencies.length * 0.95)] : 0;

  const passed = errorRate <= this.config.errorRateThreshold &&
                 avgLatencyMs <= this.config.latencyThresholdMs;

  const details = passed
    ? `Health OK: errorRate=${(errorRate * 100).toFixed(1)}%, avgLatency=${avgLatencyMs.toFixed(0)}ms, p95=${p95LatencyMs.toFixed(0)}ms (${requestCount} requests)`
    : `Health FAILED: errorRate=${(errorRate * 100).toFixed(1)}% (threshold: ${(this.config.errorRateThreshold * 100).toFixed(1)}%), avgLatency=${avgLatencyMs.toFixed(0)}ms (threshold: ${this.config.latencyThresholdMs}ms)`;

  const result: HealthCheckResult = {
    timestamp: now,
    stage: this.state.currentStage,
    percentage: this.state.rolloutPercentage,
    passed,
    metrics: { errorRate, avgLatencyMs, p95LatencyMs, requestCount, successCount, failureCount },
    details,
  };

  this.healthHistory.push(result);
  if (this.healthHistory.length > 200) {
    this.healthHistory.splice(0, this.healthHistory.length - 200);
  }

  this.state.lastHealthCheck = result;
  this.addEvent('health_check', details, { passed, errorRate, avgLatencyMs, p95LatencyMs });

  if (passed) {
    this.state.consecutiveHealthFailures = 0;
    // Auto-advance if configured
    if (this.config.autoAdvance && this.state.status === 'rolling_out' && this.state.currentStage !== 'full') {
      if (this.state.stageStartedAt && (now - this.state.stageStartedAt) >= this.config.minStageStabilityMs) {
        try {
          this.advanceStage();
          this.addEvent('auto_advance', `Auto-advanced to ${this.state.currentStage} (${this.state.rolloutPercentage}%)`);
        } catch { /* stability check will catch */ }
      }
    }
  } else {
    this.state.consecutiveHealthFailures++;
    if (this.state.consecutiveHealthFailures >= this.config.maxHealthFailures) {
      this.rollback(`Auto-rollback: ${this.state.consecutiveHealthFailures} consecutive health check failures`);
      this.addEvent('auto_rollback', `Auto-rolled back after ${this.state.consecutiveHealthFailures} consecutive failures`);
    }
  }

  return result;
}

private startHealthChecks(): void {
  this.stopHealthChecks();
  this.healthCheckTimer = setInterval(() => {
    if (this.state.status === 'rolling_out') {
      this.runHealthCheck();
    }
  }, this.config.healthCheckIntervalMs);
}

private stopHealthChecks(): void {
