/**
 * Production Rollout Controller
 * Implements controlled rollout strategy with percentage-based traffic routing,
 * shadow mode, request logging, and automatic health checks.
 *
 * Rollout stages: 0% → 5% canary → 25% → 50% → 75% → 100%
 * Each stage requires passing health checks before advancing.
 */

export type RolloutStage = 'disabled' | 'canary' | 'partial_25' | 'partial_50' | 'partial_75' | 'full';
export type RolloutStatus = 'idle' | 'rolling_out' | 'paused' | 'rolled_back' | 'complete';

export interface RolloutConfig {
  /** Current rollout percentage (0-100) */
  rolloutPercentage: number;
  /** Shadow mode: log requests without affecting responses */
  shadowMode: boolean;
  /** Log all requests for debugging */
  logAllRequests: boolean;
  /** Automatic health checks before scaling up */
  autoHealthChecks: boolean;
  /** Health check interval in ms */
  healthCheckIntervalMs: number;
  /** Minimum time at each stage before advancing (ms) */
  minStageStabilityMs: number;
  /** Error rate threshold to trigger auto-rollback (0-1) */
  errorRateThreshold: number;
  /** Latency threshold in ms to trigger auto-rollback */
  latencyThresholdMs: number;
  /** Auto-advance to next stage when health checks pass */
  autoAdvance: boolean;
  /** Max consecutive health check failures before rollback */
  maxHealthFailures: number;
}

export interface HealthCheckResult {
  timestamp: number;
  stage: RolloutStage;
  percentage: number;
  passed: boolean;
  metrics: {
    errorRate: number;
    avgLatencyMs: number;
    p95LatencyMs: number;
    requestCount: number;
    successCount: number;
    failureCount: number;
  };
  details: string;
}

export interface RolloutEvent {
  id: string;
  timestamp: number;
  type: 'stage_change' | 'health_check' | 'auto_advance' | 'auto_rollback' | 'manual_action' | 'shadow_log' | 'error';
  stage: RolloutStage;
  percentage: number;
  message: string;
  metadata?: Record<string, unknown>;
}

/** Maximum length for sanitized error strings stored in request logs. */
const MAX_REQUEST_LOG_ERROR_LENGTH = 500;

/**
 * Sanitize a raw error message before storing it in a RequestLog entry.
 * Strips stack-trace lines (everything after the first newline) and truncates
 * to MAX_REQUEST_LOG_ERROR_LENGTH to prevent sensitive internals from leaking
 * into the request log store.
 */
export function sanitizeRequestLogError(raw: string): string {
  // Remove stack trace lines (keep only the first line of the message)
  const firstLine = raw.split('\n')[0] ?? raw;
  return firstLine.substring(0, MAX_REQUEST_LOG_ERROR_LENGTH);
}

export interface RequestLog {
  id: string;
  timestamp: number;
  path: string;
  method: string;
  statusCode: number;
  latencyMs: number;
  isRolledOut: boolean;
  isShadow: boolean;
  /** Sanitized error summary (stack traces and sensitive details stripped). */
  error?: string;
}

export interface RolloutState {
  status: RolloutStatus;
  currentStage: RolloutStage;
  rolloutPercentage: number;
  stageStartedAt: number | null;
  totalRequests: number;
  rolledOutRequests: number;
  shadowRequests: number;
  errors: number;
  consecutiveHealthFailures: number;
  lastHealthCheck: HealthCheckResult | null;
  startedAt: number | null;
  completedAt: number | null;
}

const STAGE_PERCENTAGES: Record<RolloutStage, number> = {
  disabled: 0,
  canary: 5,
  partial_25: 25,
  partial_50: 50,
  partial_75: 75,
  full: 100,
};

const STAGE_ORDER: RolloutStage[] = ['disabled', 'canary', 'partial_25', 'partial_50', 'partial_75', 'full'];

const DEFAULT_CONFIG: RolloutConfig = {
  rolloutPercentage: 0,
  shadowMode: true,
  logAllRequests: true,
  autoHealthChecks: true,
  healthCheckIntervalMs: 60_000,
  minStageStabilityMs: 300_000, // 5 minutes minimum at each stage
  errorRateThreshold: 0.05,
  latencyThresholdMs: 2000,
  autoAdvance: false,
  maxHealthFailures: 3,
};

class ProductionRolloutController {
  private config: RolloutConfig;
  private state: RolloutState;
  private events: RolloutEvent[] = [];
  private requestLogs: RequestLog[] = [];
  private healthHistory: HealthCheckResult[] = [];
  private healthCheckTimer: ReturnType<typeof setInterval> | null = null;
  private recentRequests: { timestamp: number; latencyMs: number; success: boolean }[] = [];

  constructor(config?: Partial<RolloutConfig>) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.state = {
      status: 'idle',
      currentStage: 'disabled',
      rolloutPercentage: 0,
      stageStartedAt: null,
      totalRequests: 0,
      rolledOutRequests: 0,
      shadowRequests: 0,
      errors: 0,
      consecutiveHealthFailures: 0,
      lastHealthCheck: null,
      startedAt: null,
      completedAt: null,
    };
  }

  // ─── Rollout Control ─────────────────────────────────────────────────

  startRollout(): RolloutState {
    if (this.state.status === 'rolling_out') {
      throw new Error('Rollout already in progress');
    }
    this.state.status = 'rolling_out';
    this.state.currentStage = 'canary';
    this.state.rolloutPercentage = STAGE_PERCENTAGES.canary;
    this.state.stageStartedAt = Date.now();
    this.state.startedAt = Date.now();
    this.state.completedAt = null;
    this.state.consecutiveHealthFailures = 0;
    this.state.totalRequests = 0;
    this.state.rolledOutRequests = 0;
    this.state.shadowRequests = 0;
    this.state.errors = 0;
    this.recentRequests = [];

    this.addEvent('stage_change', `Rollout started at canary (${STAGE_PERCENTAGES.canary}%)`);

    if (this.config.autoHealthChecks) {
      this.startHealthChecks();
    }

    return { ...this.state };
  }

  advanceStage(): RolloutState {
    if (this.state.status !== 'rolling_out') {
      throw new Error('No active rollout to advance');
    }

    const currentIdx = STAGE_ORDER.indexOf(this.state.currentStage);
    if (currentIdx >= STAGE_ORDER.length - 1) {
      throw new Error('Already at full rollout');
    }

    // Check stability time
    if (this.state.stageStartedAt) {
      const elapsed = Date.now() - this.state.stageStartedAt;
      if (elapsed < this.config.minStageStabilityMs) {
        throw new Error(
          `Stage must be stable for ${Math.ceil(this.config.minStageStabilityMs / 1000)}s. ` +
          `Current: ${Math.ceil(elapsed / 1000)}s`
        );
      }
    }

    const nextStage = STAGE_ORDER[currentIdx + 1];
    this.state.currentStage = nextStage;
    this.state.rolloutPercentage = STAGE_PERCENTAGES[nextStage];
    this.state.stageStartedAt = Date.now();
    this.state.consecutiveHealthFailures = 0;

    this.addEvent('stage_change', `Advanced to ${nextStage} (${STAGE_PERCENTAGES[nextStage]}%)`);

    if (nextStage === 'full') {
      this.state.status = 'complete';
      this.state.completedAt = Date.now();
      this.stopHealthChecks();
      this.addEvent('stage_change', 'Rollout complete — 100% traffic');
    }

    return { ...this.state };
  }

  pauseRollout(): RolloutState {
    if (this.state.status !== 'rolling_out') {
      throw new Error('No active rollout to pause');
    }
    this.state.status = 'paused';
    this.stopHealthChecks();
    this.addEvent('manual_action', `Rollout paused at ${this.state.currentStage} (${this.state.rolloutPercentage}%)`);
    return { ...this.state };
  }

  resumeRollout(): RolloutState {
    if (this.state.status !== 'paused') {
      throw new Error('Rollout is not paused');
    }
    this.state.status = 'rolling_out';
    if (this.config.autoHealthChecks) {
      this.startHealthChecks();
    }
    this.addEvent('manual_action', `Rollout resumed at ${this.state.currentStage} (${this.state.rolloutPercentage}%)`);
    return { ...this.state };
  }

  rollback(reason: string): RolloutState {
    const prevStage = this.state.currentStage;
    const prevPct = this.state.rolloutPercentage;
    this.state.status = 'rolled_back';
    this.state.currentStage = 'disabled';
    this.state.rolloutPercentage = 0;
    this.state.completedAt = Date.now();
    this.stopHealthChecks();
    this.addEvent('manual_action', `Rollout rolled back from ${prevStage} (${prevPct}%): ${reason}`);
    return { ...this.state };
  }

  setPercentage(pct: number): RolloutState {
    if (pct < 0 || pct > 100) throw new Error('Percentage must be 0-100');
    this.state.rolloutPercentage = pct;
    // Find closest stage
    let closestStage: RolloutStage = 'disabled';
    for (const stage of STAGE_ORDER) {
      if (STAGE_PERCENTAGES[stage] <= pct) closestStage = stage;
    }
    this.state.currentStage = closestStage;
    this.addEvent('manual_action', `Rollout percentage manually set to ${pct}%`);
    return { ...this.state };
  }

  // ─── Request Routing ─────────────────────────────────────────────────

  shouldRouteToNew(): boolean {
    if (this.state.rolloutPercentage === 0) return false;
    if (this.state.rolloutPercentage >= 100) return true;
    return Math.random() * 100 < this.state.rolloutPercentage;
  }

  recordRequest(req: {
    path: string;
    method: string;
    statusCode: number;
    latencyMs: number;
    isRolledOut: boolean;
    error?: string;
  }): void {
    this.state.totalRequests++;
    const isShadow = this.config.shadowMode && req.isRolledOut;
    if (req.isRolledOut) this.state.rolledOutRequests++;
    if (isShadow) this.state.shadowRequests++;
    if (req.error || req.statusCode >= 500) this.state.errors++;

    // Track for health checks
    this.recentRequests.push({
      timestamp: Date.now(),
      latencyMs: req.latencyMs,
      success: !req.error && req.statusCode < 500,
    });
    // Keep only last 5 minutes of requests
    const cutoff = Date.now() - 300_000;
    this.recentRequests = this.recentRequests.filter(r => r.timestamp > cutoff);

    if (this.config.logAllRequests) {
      const log: RequestLog = {
        id: `req_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
        timestamp: Date.now(),
        path: req.path,
        method: req.method,
        statusCode: req.statusCode,
        latencyMs: req.latencyMs,
        isRolledOut: req.isRolledOut,
        isShadow,
        error: req.error,
      };
      this.requestLogs.push(log);
      if (this.requestLogs.length > 1000) {
        this.requestLogs.splice(0, this.requestLogs.length - 1000);
      }

      if (isShadow) {
        this.addEvent('shadow_log', `Shadow request: ${req.method} ${req.path} → ${req.statusCode} (${req.latencyMs}ms)`, {
          path: req.path, method: req.method, statusCode: req.statusCode, latencyMs: req.latencyMs,
        });
      }
    }
  }

  // ─── Health Checks ───────────────────────────────────────────────────

  runHealthCheck(): HealthCheckResult {
    const now = Date.now();
    const windowMs = 300_000; // 5 min window
    const recent = this.recentRequests.filter(r => r.timestamp > now - windowMs);

    const requestCount = recent.length;
    const successCount = recent.filter(r => r.success).length;
    const failureCount = requestCount - successCount;
    const errorRate = requestCount > 0 ? failureCount / requestCount : 0;
    const latencies = recent.map(r => r.latencyMs).sort((a, b) => a - b);
    const avgLatencyMs = latencies.length > 0 ? latencies.reduce((s, l) => s + l, 0) / latencies.length : 0;
    const p95LatencyMs = latencies.length > 0 ? latencies[Math.floor(latencies.length * 0.95)] : 0;

    const passed = errorRate <= this.config.errorRateThreshold &&
                   avgLatencyMs <= this.config.latencyThresholdMs;

    const details = passed
      ? `Health OK: errorRate=${(errorRate * 100).toFixed(1)}%, avgLatency=${avgLatencyMs.toFixed(0)}ms, p95=${p95LatencyMs.toFixed(0)}ms (${requestCount} requests)`
      : `Health FAILED: errorRate=${(errorRate * 100).toFixed(1)}% (threshold: ${(this.config.errorRateThreshold * 100).toFixed(1)}%), avgLatency=${avgLatencyMs.toFixed(0)}ms (threshold: ${this.config.latencyThresholdMs}ms)`;

    const result: HealthCheckResult = {
      timestamp: now,
      stage: this.state.currentStage,
      percentage: this.state.rolloutPercentage,
      passed,
      metrics: { errorRate, avgLatencyMs, p95LatencyMs, requestCount, successCount, failureCount },
      details,
    };

    this.healthHistory.push(result);
    if (this.healthHistory.length > 200) {
      this.healthHistory.splice(0, this.healthHistory.length - 200);
    }

    this.state.lastHealthCheck = result;
    this.addEvent('health_check', details, { passed, errorRate, avgLatencyMs, p95LatencyMs });

    if (passed) {
      this.state.consecutiveHealthFailures = 0;
      // Auto-advance if configured
      if (this.config.autoAdvance && this.state.status === 'rolling_out' && this.state.currentStage !== 'full') {
        if (this.state.stageStartedAt && (now - this.state.stageStartedAt) >= this.config.minStageStabilityMs) {
          try {
            this.advanceStage();
            this.addEvent('auto_advance', `Auto-advanced to ${this.state.currentStage} (${this.state.rolloutPercentage}%)`);
          } catch { /* stability check will catch */ }
        }
      }
    } else {
      this.state.consecutiveHealthFailures++;
      if (this.state.consecutiveHealthFailures >= this.config.maxHealthFailures) {
        this.rollback(`Auto-rollback: ${this.state.consecutiveHealthFailures} consecutive health check failures`);
        this.addEvent('auto_rollback', `Auto-rolled back after ${this.state.consecutiveHealthFailures} consecutive failures`);
      }
    }

    return result;
  }

  private startHealthChecks(): void {
    this.stopHealthChecks();
    this.healthCheckTimer = setInterval(() => {
      if (this.state.status === 'rolling_out') {
        this.runHealthCheck();
      }
    }, this.config.healthCheckIntervalMs);
  }

  private stopHealthChecks(): void {
    if (this.healthCheckTimer) {
      clearInterval(this.healthCheckTimer);
      this.healthCheckTimer = null;
    }
  }

  // ─── Configuration ───────────────────────────────────────────────────

  updateConfig(updates: Partial<RolloutConfig>): RolloutConfig {
    this.config = { ...this.config, ...updates };
    if (updates.rolloutPercentage !== undefined) {
      this.state.rolloutPercentage = updates.rolloutPercentage;
    }
    if (updates.shadowMode !== undefined || updates.logAllRequests !== undefined) {
      this.addEvent('manual_action', `Config updated: shadow=${this.config.shadowMode}, logAll=${this.config.logAllRequests}`);
    }
    return { ...this.config };
  }

  getConfig(): RolloutConfig {
    return { ...this.config };
  }

  // ─── State & History ─────────────────────────────────────────────────

  getState(): RolloutState {
    return { ...this.state };
  }

  getEvents(limit = 50): RolloutEvent[] {
    return this.events.slice(-limit);
  }

  getRequestLogs(limit = 100): RequestLog[] {
    return this.requestLogs.slice(-limit);
  }

  getHealthHistory(limit = 50): HealthCheckResult[] {
    return this.healthHistory.slice(-limit);
  }

  getMetrics(): {
    state: RolloutState;
    config: RolloutConfig;
    healthHistory: HealthCheckResult[];
    recentEvents: RolloutEvent[];
    requestSummary: {
      total: number;
      rolledOut: number;
      shadow: number;
      errors: number;
      errorRate: number;
      avgLatencyMs: number;
    };
  } {
    const recent = this.recentRequests;
    const latencies = recent.map(r => r.latencyMs);
    return {
      state: { ...this.state },
      config: { ...this.config },
      healthHistory: this.healthHistory.slice(-10),
      recentEvents: this.events.slice(-20),
      requestSummary: {
        total: this.state.totalRequests,
        rolledOut: this.state.rolledOutRequests,
        shadow: this.state.shadowRequests,
        errors: this.state.errors,
        errorRate: this.state.totalRequests > 0 ? this.state.errors / this.state.totalRequests : 0,
        avgLatencyMs: latencies.length > 0 ? latencies.reduce((s, l) => s + l, 0) / latencies.length : 0,
      },
    };
  }

  // ─── Helpers ─────────────────────────────────────────────────────────

  private addEvent(type: RolloutEvent['type'], message: string, metadata?: Record<string, unknown>): void {
    this.events.push({
      id: `evt_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
      timestamp: Date.now(),
      type,
      stage: this.state.currentStage,
      percentage: this.state.rolloutPercentage,
      message,
      metadata,
    });
    if (this.events.length > 500) {
      this.events.splice(0, this.events.length - 500);
    }
  }

  reset(): void {
    this.stopHealthChecks();
    this.state = {
      status: 'idle',
      currentStage: 'disabled',
      rolloutPercentage: 0,
      stageStartedAt: null,
      totalRequests: 0,
      rolledOutRequests: 0,
      shadowRequests: 0,
      errors: 0,
      consecutiveHealthFailures: 0,
      lastHealthCheck: null,
      startedAt: null,
      completedAt: null,
    };
    this.events = [];
    this.requestLogs = [];
    this.healthHistory = [];
    this.recentRequests = [];
  }
}

// ─── Singleton ─────────────────────────────────────────────────────────

let instance: ProductionRolloutController | null = null;

export function getRolloutController(): ProductionRolloutController {
  if (!instance) instance = new ProductionRolloutController();
  return instance;
}

export function resetRolloutController(): void {
  if (instance) instance.reset();
  instance = null;
}

export { ProductionRolloutController };

