const adminGuard = protectedProcedure.use(({ ctx, next }) => {
  if (ctx.user.role !== 'admin') throw new TRPCError({ code: 'FORBIDDEN', message: 'Admin access required' });
  return next({ ctx });
});

export const deploymentRouter = router({
  // ─── Dashboard ────────────────────────────────────────────────────────
  getDashboardData: adminGuard.query(async () => {
    const deployer = getWebsiteContentDeployer();
    const bridge = getSelfImproveBridge();
    const scanner = getClosedLoopScanner();
    let gov;
    try { gov = await getGovernanceIntegration().takeSnapshot(); } catch { gov = null; }
    let dbStats;
    try { dbStats = await getDeploymentStats(); } catch { dbStats = null; }
    return {
      deployer: deployer.getStats(),
      bridge: bridge.getStatus(),
      scanner: scanner.getStats(),
      governance: gov,
      monitor: getMonitorStatus(),
      dbStats,
    };
  }),

  // ─── Governance ───────────────────────────────────────────────────────
  getGovernanceSnapshot: adminGuard.query(async () => getGovernanceIntegration().takeSnapshot()),
  getGovernanceScore: adminGuard.query(async () => {
    const s = await getGovernanceIntegration().getGovernanceScore();
    return { score: s, percent: `${(s * 100).toFixed(1)}%` };
  }),
  checkGovernanceRegression: adminGuard
    .input(z.object({ threshold: z.number().min(0).max(1).default(0.05) }))
    .query(async ({ input }) => getGovernanceIntegration().detectRegression(input.threshold)),
  refreshGovernanceCache: adminGuard.mutation(async () => {
    const gi = getGovernanceIntegration();
    gi.clearCache();
    const snap = await gi.takeSnapshot();
    return { success: true, score: snap.overallScore, status: snap.status };
  }),

  // ─── Deployer ─────────────────────────────────────────────────────────
  listDeployments: adminGuard
    .input(z.object({ limit: z.number().min(1).max(100).default(20) }))
    .query(({ input }) => getWebsiteContentDeployer().getDeploymentHistory(input.limit)),
  getDeployment: adminGuard
    .input(z.object({ id: z.string() }))
    .query(({ input }) => {
      const r = getWebsiteContentDeployer().getDeployment(input.id);
      if (!r) throw new TRPCError({ code: 'NOT_FOUND' });
      return r;
    }),
  rollbackDeployment: adminGuard
    .input(z.object({ deploymentId: z.string(), reason: z.string() }))
    .mutation(async ({ input }) => getWebsiteContentDeployer().rollback(input.deploymentId, input.reason)),
  getDeployerConfig: adminGuard.query(() => getWebsiteContentDeployer().getConfig()),
  updateDeployerConfig: adminGuard
    .input(z.object({
      maxConcurrent: z.number().min(1).max(5).optional(),
      requireGovernance: z.boolean().optional(),
      autoRollbackOnFailure: z.boolean().optional(),
      maxPatchesPerDeployment: z.number().min(1).max(50).optional(),
      dryRun: z.boolean().optional(),
    }))
    .mutation(({ input }) => { getWebsiteContentDeployer().updateConfig(input); return { success: true }; }),
  manualDeploy: adminGuard
    .input(z.object({
      patches: z.array(z.object({
        targetFile: z.string(),
        findText: z.string(),
        replaceText: z.string(),
        description: z.string(),
        category: z.enum(['headline', 'cta', 'proof', 'objection_handling', 'structure', 'tone', 'clarity', 'bug_fix', 'other']).default('other'),
      })),
      mode: z.enum(['staging', 'production']).default('staging'),
      reason: z.string(),
    }))
    .mutation(async ({ input }) => {
      try { await getClosedLoopScanner().capturePreDeploySnapshot(); } catch { /* non-critical */ }
      return getWebsiteContentDeployer().deploy({ patches: input.patches, mode: input.mode, source: 'manual', reason: input.reason });
    }),

  // ─── Bridge ───────────────────────────────────────────────────────────
  getBridgeEvents: adminGuard
    .input(z.object({ limit: z.number().min(1).max(100).default(20) }))
    .query(({ input }) => getSelfImproveBridge().getEvents(input.limit)),
  resetCircuitBreaker: adminGuard.mutation(() => { getSelfImproveBridge().resetCircuitBreaker(); return { success: true }; }),
  getBridgeConfig: adminGuard.query(() => getSelfImproveBridge().getConfig()),
  updateBridgeConfig: adminGuard
    .input(z.object({
      enabled: z.boolean().optional(),
      minConfidenceForPromotion: z.number().min(0).max(1).optional(),
      minImprovementDelta: z.number().min(0).max(1).optional(),
      circuitBreakerThreshold: z.number().min(1).max(20).optional(),
      rateLimitPerMinute: z.number().min(1).max(60).optional(),
    }))
    .mutation(({ input }) => { getSelfImproveBridge().updateConfig(input); return { success: true }; }),

  // ─── Scanner ──────────────────────────────────────────────────────────
  triggerScan: adminGuard
    .input(z.object({ deploymentId: z.string() }))
    .mutation(async ({ input }) => getClosedLoopScanner().scanDeployment(input.deploymentId)),
  capturePreDeploySnapshot: adminGuard.mutation(async () => {
    const s = await getClosedLoopScanner().capturePreDeploySnapshot();
    return { success: true, score: s.overallScore, status: s.status };
  }),
  getScanResults: adminGuard
    .input(z.object({ limit: z.number().min(1).max(100).default(20) }))
    .query(({ input }) => getClosedLoopScanner().getScanHistory(input.limit)),
  getScannerConfig: adminGuard.query(() => getClosedLoopScanner().getConfig()),
  updateScannerConfig: adminGuard
    .input(z.object({
      enabled: z.boolean().optional(),
      autoScanAfterDeploy: z.boolean().optional(),
      degradationThreshold: z.number().min(-1).max(0).optional(),
      autoRollbackOnDegradation: z.boolean().optional(),
      useRealGovernance: z.boolean().optional(),
    }))
    .mutation(({ input }) => { getClosedLoopScanner().updateConfig(input); return { success: true }; }),
  setBaseline: adminGuard
    .input(z.object({ metrics: z.record(z.number()) }))
    .mutation(({ input }) => { getClosedLoopScanner().setBaseline(input.metrics); return { success: true }; }),

  // ─── Autonomous Monitor (Gap 1) ──────────────────────────────────────
  getMonitorStatus: adminGuard.query(() => getMonitorStatus()),
  getMonitorHistory: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(({ input }) => getMonitorHistory(input.limit)),
  updateMonitorConfig: adminGuard
    .input(z.object({
      enabled: z.boolean().optional(),
      intervalMs: z.number().min(60000).max(86400000).optional(),
      maxPromotionsPerCycle: z.number().min(1).max(20).optional(),
      maxRollbacksPerCycle: z.number().min(1).max(20).optional(),
      enablePostDeployScans: z.boolean().optional(),
      dryRun: z.boolean().optional(),
    }))
    .mutation(({ input }) => ({ success: true, config: updateMonitorConfig(input) })),
  startMonitor: adminGuard.mutation(() => { startAutonomousMonitor(); return { success: true, status: getMonitorStatus() }; }),
  stopMonitor: adminGuard.mutation(() => { stopAutonomousMonitor(); return { success: true, status: getMonitorStatus() }; }),
  triggerMonitorCycle: adminGuard.mutation(async () => ({ success: true, cycle: await triggerMonitorCycle() })),

  // ─── CMS Content Layer (Gap 2) ───────────────────────────────────────
  upsertContentOverride: adminGuard
    .input(z.object({
      contentKey: z.string().min(1).max(256),
      contentValue: z.string(),
      contentType: z.enum(['text', 'html', 'json', 'markdown']).default('text'),
      source: z.enum(['deployment', 'experiment', 'manual', 'ai-generated']).default('manual'),
      deploymentId: z.string().nullable().optional(),
      experimentId: z.string().nullable().optional(),
    }))
    .mutation(async ({ input }) => upsertContentOverride(input)),
  getContentOverride: adminGuard
    .input(z.object({ contentKey: z.string() }))
    .query(async ({ input }) => {
      const r = await getContentOverride(input.contentKey);
      if (!r) throw new TRPCError({ code: 'NOT_FOUND' });
      return r;
    }),
  listContentOverrides: adminGuard
    .input(z.object({
      prefix: z.string().optional(),
      source: z.string().optional(),
      activeOnly: z.boolean().default(false),
      limit: z.number().min(1).max(500).default(100),
    }))
    .query(async ({ input }) => listContentOverrides(input)),
  deleteContentOverride: adminGuard
    .input(z.object({ contentKey: z.string() }))
    .mutation(async ({ input }) => ({ success: await deleteContentOverride(input.contentKey) })),
  toggleContentOverride: adminGuard
    .input(z.object({ contentKey: z.string(), active: z.boolean() }))
    .mutation(async ({ input }) => ({
      success: input.active
        ? await activateContentOverride(input.contentKey)
        : await deactivateContentOverride(input.contentKey),
    })),
  applyDeploymentOverrides: adminGuard
    .input(z.object({
      deploymentId: z.string(),
      overrides: z.array(z.object({ key: z.string(), value: z.string(), type: z.string().optional() })),
    }))
    .mutation(async ({ input }) => ({ success: true, applied: await applyDeploymentOverrides(input.deploymentId, input.overrides) })),
  rollbackDeploymentOverrides: adminGuard
    .input(z.object({ deploymentId: z.string() }))
    .mutation(async ({ input }) => ({ success: true, removed: await rollbackDeploymentOverrides(input.deploymentId) })),
  clearContentCache: adminGuard.mutation(() => { clearContentCache(); return { success: true }; }),

  // ─── Persistence Layer (Gap 3) ────────────────────────────────────────
  getPersistedDeployments: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(async ({ input }) => getDeploymentRecords(input.limit)),
  getPersistedDeployment: adminGuard
    .input(z.object({ deploymentId: z.string() }))
    .query(async ({ input }) => {
      const r = await getDeploymentRecord(input.deploymentId);
      if (!r) throw new TRPCError({ code: 'NOT_FOUND' });
      return r;
    }),
  getPersistedScans: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(async ({ input }) => getPersistedScans(input.limit)),
  getPersistedMonitorCycles: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(async ({ input }) => getMonitorCycles(input.limit)),
  getPersistedGovernanceSnapshots: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(async ({ input }) => getGovernanceSnapshots(input.limit)),
  getDeploymentStats: adminGuard.query(async () => getDeploymentStats()),

  // ─── Alerting Pipeline ─────────────────────────────────────────────────
  getAlertPipelineStatus: adminGuard.query(async () => getAlertPipelineStatus()),
  getAlertHistory: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(async ({ input }) => getAlertHistory(input.limit)),
  getAlertStats: adminGuard.query(async () => getAlertStats()),
  getAlertRules: adminGuard.query(async () => getAlertRules()),
  updateAlertRule: adminGuard
    .input(z.object({
      ruleId: z.string(),
      enabled: z.boolean().optional(),
      cooldownMs: z.number().min(0).optional(),
      minSeverity: z.enum(['info', 'warning', 'critical']).optional(),
    }))
    .mutation(async ({ input }) => {
      const { ruleId, ...updates } = input;
      const rule = updateAlertRule(ruleId, updates);
      if (!rule) throw new TRPCError({ code: 'NOT_FOUND', message: `Rule ${ruleId} not found` });
      return rule;
    }),
  updateAlertPipelineConfig: adminGuard
    .input(z.object({
      enabled: z.boolean().optional(),
      maxAlertsPerHour: z.number().min(1).max(100).optional(),
      globalCooldownMs: z.number().min(0).optional(),
      includeMetrics: z.boolean().optional(),
    }))
    .mutation(async ({ input }) => updateAlertPipelineConfig(input)),
  sendManualAlert: adminGuard
    .input(z.object({
      title: z.string().min(1).max(200),
      content: z.string().min(1).max(5000),
      severity: z.enum(['info', 'warning', 'critical']).default('info'),
    }))
    .mutation(async ({ input }) => sendManualAlert(input.title, input.content, input.severity)),
  startAlertPipeline: adminGuard.mutation(async () => {
    startAlertingPipeline();
    return { started: true };
  }),
  stopAlertPipeline: adminGuard.mutation(async () => {
    stopAlertingPipeline();
    return { stopped: true };
  }),

  // ─── Slack Integration ─────────────────────────────────────────────
  getSlackStatus: adminGuard.query(async () => getSlackStatus()),

  testSlackWebhook: adminGuard
    .input(z.object({ webhookUrl: z.string().url().optional() }))
    .mutation(async ({ input }) => testSlackWebhook(input.webhookUrl)),

  configureSlack: adminGuard
    .input(z.object({
      webhookUrl: z.string().url().optional(),
      enabled: z.boolean().optional(),
    }))
    .mutation(async ({ input }) => {
      const config: any = { channels: {} };
      if (input.webhookUrl !== undefined) {
        config.channels.slackWebhookUrl = input.webhookUrl;
      }
      return updateAlertPipelineConfig(config);
    }),

  // ─── Production Rollout Controller ─────────────────────────────────
  getRolloutState: adminGuard.query(() => getRolloutController().getState()),
  getRolloutConfig: adminGuard.query(() => getRolloutController().getConfig()),
  getRolloutMetrics: adminGuard.query(() => getRolloutController().getMetrics()),
  getRolloutEvents: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(({ input }) => getRolloutController().getEvents(input.limit)),
  getRolloutHealthHistory: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(({ input }) => getRolloutController().getHealthHistory(input.limit)),
  getRolloutRequestLogs: adminGuard
    .input(z.object({ limit: z.number().min(1).max(500).default(100) }))
    .query(({ input }) => getRolloutController().getRequestLogs(input.limit)),

  startRollout: adminGuard.mutation(() => getRolloutController().startRollout()),
  advanceRolloutStage: adminGuard.mutation(() => getRolloutController().advanceStage()),
  pauseRollout: adminGuard.mutation(() => getRolloutController().pauseRollout()),
  resumeRollout: adminGuard.mutation(() => getRolloutController().resumeRollout()),
  rollbackRollout: adminGuard
    .input(z.object({ reason: z.string().min(1).max(500) }))
    .mutation(({ input }) => getRolloutController().rollback(input.reason)),
  setRolloutPercentage: adminGuard
    .input(z.object({ percentage: z.number().min(0).max(100) }))
    .mutation(({ input }) => getRolloutController().setPercentage(input.percentage)),
  runRolloutHealthCheck: adminGuard.mutation(() => getRolloutController().runHealthCheck()),
  updateRolloutConfig: adminGuard
    .input(z.object({
      shadowMode: z.boolean().optional(),
      logAllRequests: z.boolean().optional(),
      autoHealthChecks: z.boolean().optional(),
      healthCheckIntervalMs: z.number().min(10000).max(600000).optional(),
      minStageStabilityMs: z.number().min(30000).max(3600000).optional(),
      errorRateThreshold: z.number().min(0).max(1).optional(),
      latencyThresholdMs: z.number().min(100).max(30000).optional(),
      autoAdvance: z.boolean().optional(),
      maxHealthFailures: z.number().min(1).max(20).optional(),
    }))
    .mutation(({ input }) => ({ success: true, config: getRolloutController().updateConfig(input) })),

  // ─── Multi-Channel Notifications ──────────────────────────────────────
  getNotificationChannels: adminGuard.query(() => getMultiChannelNotifier().getChannels()),
  getNotificationStats: adminGuard.query(() => getMultiChannelNotifier().getStats()),
  getNotificationSummary: adminGuard.query(() => getMultiChannelNotifier().getSummary()),
  getNotificationDeliveryLog: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(({ input }) => getMultiChannelNotifier().getDeliveryLog(input.limit)),

  registerNotificationChannel: adminGuard
    .input(z.object({
      id: z.string().min(1).max(100),
      type: z.enum(['in_app', 'slack', 'email', 'sms', 'webhook']),
      name: z.string().min(1).max(200),
      enabled: z.boolean().default(true),
      minSeverity: z.enum(['info', 'warning', 'critical']).default('warning'),
      maxPerHour: z.number().min(1).max(200).default(30),
      retryCount: z.number().min(0).max(5).default(2),
      retryDelayMs: z.number().min(500).max(30000).default(2000),
      settings: z.record(z.string()).default({}),
    }))
    .mutation(({ input }) => {
      getMultiChannelNotifier().registerChannel(input);
      return { success: true, channel: input };
    }),

  updateNotificationChannel: adminGuard
    .input(z.object({
      channelId: z.string(),
      updates: z.object({
        name: z.string().optional(),
        enabled: z.boolean().optional(),
        minSeverity: z.enum(['info', 'warning', 'critical']).optional(),
        maxPerHour: z.number().min(1).max(200).optional(),
        retryCount: z.number().min(0).max(5).optional(),
        retryDelayMs: z.number().min(500).max(30000).optional(),
        settings: z.record(z.string()).optional(),
      }),
    }))
    .mutation(({ input }) => {
      const updated = getMultiChannelNotifier().updateChannel(input.channelId, input.updates);
      if (!updated) throw new TRPCError({ code: 'NOT_FOUND', message: `Channel ${input.channelId} not found` });
      return { success: true, channel: updated };
    }),

  removeNotificationChannel: adminGuard
    .input(z.object({ channelId: z.string() }))
    .mutation(({ input }) => {
      const removed = getMultiChannelNotifier().removeChannel(input.channelId);
      if (!removed) throw new TRPCError({ code: 'NOT_FOUND', message: `Channel ${input.channelId} not found` });
      return { success: true };
    }),

  testNotificationChannel: adminGuard
    .input(z.object({ channelId: z.string() }))
    .mutation(async ({ input }) => {
      const result = await getMultiChannelNotifier().testChannel(input.channelId);
      return result;
    }),

  dispatchTestNotification: adminGuard
    .input(z.object({
      title: z.string().min(1).max(500),
      content: z.string().min(1).max(5000),
      severity: z.enum(['info', 'warning', 'critical']).default('info'),
    }))
    .mutation(async ({ input }) => {
      const results = await getMultiChannelNotifier().dispatch({
        title: input.title,
        content: input.content,
        severity: input.severity,
        source: 'admin-manual-test',
        timestamp: Date.now(),
      });
      return {
        success: results.some(r => r.success),
        results,
        delivered: results.filter(r => r.success).length,
        failed: results.filter(r => !r.success).length,
      };
    }),

  // ─── Rollout Persistence ──────────────────────────────────────────────
  saveRolloutSnapshot: adminGuard.mutation(async () => {
    const ctrl = getRolloutController();
    const state = ctrl.getState();
    const config = ctrl.getConfig();
    const metrics = ctrl.getMetrics();
    const id = await saveRolloutState({
      status: state.status,
      currentStage: state.currentStage,
      percentage: state.percentage,
      shadowMode: state.shadowMode,
      logAllRequests: state.logAllRequests,
      totalRequests: metrics.totalRequests,
      newVersionRequests: metrics.newVersionRequests,
      healthChecksPassed: metrics.healthChecksPassed,
      healthChecksFailed: metrics.healthChecksFailed,
      consecutiveFailures: metrics.consecutiveFailures,
      config,
      startedAt: state.startedAt,
      completedAt: state.completedAt,
    });
    return { success: true, rolloutId: id };
  }),

  loadRolloutSnapshot: adminGuard.query(async () => {
    const snapshot = await loadRolloutState();
    return snapshot;
  }),

  recordRolloutAuditEvent: adminGuard
    .input(z.object({
      eventType: z.string(),
      stage: z.number().optional(),
      percentage: z.number().optional(),
      details: z.record(z.string(), z.unknown()).optional(),
    }))
    .mutation(async ({ input }) => {
      const rolloutId = getActiveRolloutId();
      if (!rolloutId) throw new TRPCError({ code: 'BAD_REQUEST', message: 'No active rollout to record event for' });
      const eventId = await recordRolloutEvent({
        rolloutId,
        eventType: input.eventType,
        stage: input.stage,
        percentage: input.percentage,
        details: input.details,
        timestamp: Date.now(),
      });
      return { success: true, eventId };
    }),

  getRolloutStateHistory: adminGuard
    .input(z.object({ limit: z.number().min(1).max(100).default(20) }))
    .query(async ({ input }) => getRolloutStateHistory(input.limit)),

  getRolloutEventHistory: adminGuard
    .input(z.object({
      rolloutId: z.number().optional(),
      limit: z.number().min(1).max(200).default(50),
      eventType: z.string().optional(),
    }))
    .query(async ({ input }) => getRolloutEventHistory(input)),

  getRolloutPersistenceStats: adminGuard.query(async () => getRolloutPersistenceStats()),

  // ─── Rollout Auto-Restore ─────────────────────────────────────────────

  getAutoRestoreStatus: adminGuard.query(async () => getAutoRestoreStatus()),

  getAutoRestoreConfig: adminGuard.query(async () => getAutoRestoreConfig()),

  updateAutoRestoreConfig: adminGuard.input(z.object({
    enabled: z.boolean().optional(),
    restoreAsPaused: z.boolean().optional(),
    notifyOnRestore: z.boolean().optional(),
    maxStateAgeMs: z.number().min(60000).optional(),
  })).mutation(async ({ input }) => updateAutoRestoreConfig(input)),

  triggerAutoRestore: adminGuard.mutation(async () => {
    const result = await autoRestoreRollout();
    return result;
  }),
  // ─── Rollout Comparison ────────────────────────────────────────────────
  getComparableRollouts: adminGuard.query(async () => getComparableRollouts()),
  compareRollouts: adminGuard
    .input(z.object({
      rolloutIdA: z.number(),
      rolloutIdB: z.number(),
    }))
    .query(async ({ input }) => compareRollouts(input)),

  // ─── Notification Preferences ──────────────────────────────────────────
  getNotificationPreferences: adminGuard.query(async () => {
    const prefs = getNotificationPreferences();
    return prefs.getState();
  }),
  getNotificationPreferencesSummary: adminGuard.query(async () => {
    const prefs = getNotificationPreferences();
    return prefs.getSummary();
  }),
  getNotificationProfiles: adminGuard.query(async () => {
    const prefs = getNotificationPreferences();
    return prefs.getProfiles();
  }),
  getActiveNotificationProfile: adminGuard.query(async () => {
    const prefs = getNotificationPreferences();
    return prefs.getActiveProfile();
  }),
  setActiveNotificationProfile: adminGuard
    .input(z.object({ profileId: z.string() }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      const success = prefs.setActiveProfile(input.profileId);
      if (!success) throw new TRPCError({ code: 'NOT_FOUND', message: 'Profile not found' });
      return { success: true, activeProfile: prefs.getActiveProfile() };
    }),
  createNotificationProfile: adminGuard
    .input(z.object({
      name: z.string().min(1).max(100),
      description: z.string().max(500).optional().default(''),
      globalMute: z.boolean().optional().default(false),
      escalationThreshold: z.number().min(1).max(10).optional().default(3),
      quietHours: z.object({
        enabled: z.boolean(),
        startHour: z.number().min(0).max(23),
        endHour: z.number().min(0).max(23),
        daysOfWeek: z.array(z.number().min(0).max(6)),
        bypassSeverity: z.enum(['info', 'warning', 'critical']),
      }).optional(),
      channelPreferences: z.array(z.object({
        channelId: z.string(),
        minSeverity: z.enum(['info', 'warning', 'critical']),
        maxPerHour: z.number().min(1).max(1000),
        enabled: z.boolean(),
        label: z.string().optional(),
      })).optional(),
    }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      return prefs.createProfile({
        name: input.name,
        description: input.description,
        globalMute: input.globalMute,
        escalationThreshold: input.escalationThreshold,
        quietHours: input.quietHours ?? {
          enabled: false,
          startHour: 22,
          endHour: 8,
          daysOfWeek: [0, 1, 2, 3, 4, 5, 6],
          bypassSeverity: 'critical',
        },
        channelPreferences: input.channelPreferences ?? [],
      });
    }),
  updateNotificationProfile: adminGuard
    .input(z.object({
      profileId: z.string(),
      name: z.string().min(1).max(100).optional(),
      description: z.string().max(500).optional(),
      globalMute: z.boolean().optional(),
      escalationThreshold: z.number().min(1).max(10).optional(),
      quietHours: z.object({
        enabled: z.boolean(),
        startHour: z.number().min(0).max(23),
        endHour: z.number().min(0).max(23),
        daysOfWeek: z.array(z.number().min(0).max(6)),
        bypassSeverity: z.enum(['info', 'warning', 'critical']),
      }).optional(),
      channelPreferences: z.array(z.object({
        channelId: z.string(),
        minSeverity: z.enum(['info', 'warning', 'critical']),
        maxPerHour: z.number().min(1).max(1000),
        enabled: z.boolean(),
        label: z.string().optional(),
      })).optional(),
    }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      const result = prefs.updateProfile(input.profileId, input);
      if (!result) throw new TRPCError({ code: 'NOT_FOUND', message: 'Profile not found' });
      return result;
    }),
  deleteNotificationProfile: adminGuard
    .input(z.object({ profileId: z.string() }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      const success = prefs.deleteProfile(input.profileId);
      if (!success) throw new TRPCError({ code: 'BAD_REQUEST', message: 'Cannot delete active or default profile' });
      return { success: true };
    }),
  updateQuietHours: adminGuard
    .input(z.object({
      profileId: z.string(),
      quietHours: z.object({
        enabled: z.boolean(),
        startHour: z.number().min(0).max(23),
        endHour: z.number().min(0).max(23),
        daysOfWeek: z.array(z.number().min(0).max(6)),
        bypassSeverity: z.enum(['info', 'warning', 'critical']),
      }),
    }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      const success = prefs.updateQuietHours(input.profileId, input.quietHours);
      if (!success) throw new TRPCError({ code: 'NOT_FOUND', message: 'Profile not found' });
      return { success: true };
    }),
  updateChannelPreference: adminGuard
    .input(z.object({
      profileId: z.string(),
      channelId: z.string(),
      minSeverity: z.enum(['info', 'warning', 'critical']).optional(),
      maxPerHour: z.number().min(1).max(1000).optional(),
      enabled: z.boolean().optional(),
      label: z.string().optional(),
    }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      const success = prefs.updateChannelPreference(input.profileId, input.channelId, input);
      if (!success) throw new TRPCError({ code: 'NOT_FOUND', message: 'Profile not found' });
      return { success: true };
    }),
  setGlobalNotificationsDisabled: adminGuard
    .input(z.object({ disabled: z.boolean() }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      prefs.setGlobalDisabled(input.disabled);
      return { success: true, disabled: input.disabled };
    }),
  getNotificationChangeLog: adminGuard.query(async () => {
    const prefs = getNotificationPreferences();
    return prefs.getChangeLog();
  }),

  // ─── Rollout Scheduling ─────────────────────────────────────────────
  createScheduledRollout: adminGuard.input(z.object({
    name: z.string(),
    description: z.string(),
    scheduledAt: z.number(),
    recurrence: z.enum(['once', 'daily', 'weekly', 'biweekly', 'monthly']).optional(),
    autoAdvance: z.boolean().optional(),
    maxDurationMs: z.number().optional(),
    tags: z.array(z.string()).optional(),
    preChecks: z.array(z.string()).optional(),
    rolloutConfigOverrides: z.object({
      shadowMode: z.boolean().optional(),
      logAllRequests: z.boolean().optional(),
      autoHealthChecks: z.boolean().optional(),
      errorRateThreshold: z.number().optional(),
      latencyThresholdMs: z.number().optional(),
    }).optional(),
  })).mutation(async ({ input, ctx }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.createSchedule({ ...input, createdBy: ctx.user.name || 'admin' });
  }),
  cancelScheduledRollout: adminGuard.input(z.object({
    id: z.string(),
    reason: z.string(),
  })).mutation(async ({ input, ctx }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.cancelSchedule(input.id, input.reason, ctx.user.name || 'admin');
  }),
  pauseScheduledRollout: adminGuard.input(z.object({ id: z.string() })).mutation(async ({ input, ctx }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.pauseSchedule(input.id, ctx.user.name || 'admin');
  }),
  resumeScheduledRollout: adminGuard.input(z.object({ id: z.string() })).mutation(async ({ input, ctx }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.resumeSchedule(input.id, ctx.user.name || 'admin');
  }),
  rescheduleRollout: adminGuard.input(z.object({
    id: z.string(),
    newTime: z.number(),
