import { z } from 'zod';
import { router, protectedProcedure } from '../_core/trpc';
import { TRPCError } from '@trpc/server';
import { getWebsiteContentDeployer } from './website-content-deployer';
import { getSelfImproveBridge } from './self-improve-bridge';
import { getClosedLoopScanner } from './closed-loop-scanner';
import { getGovernanceIntegration } from './governance-integration';
import {
  getMonitorStatus,
  getMonitorHistory,
  updateMonitorConfig,
  triggerMonitorCycle,
  startAutonomousMonitor,
  stopAutonomousMonitor,
} from './autonomous-experiment-monitor';
import {
  upsertContentOverride,
  getContentOverride,
  listContentOverrides,
  deleteContentOverride,
  deactivateContentOverride,
  activateContentOverride,
  applyDeploymentOverrides,
  rollbackDeploymentOverrides,
  clearContentCache,
} from './cms-content-layer';
import {
  getDeploymentRecords,
  getDeploymentRecord,
  getScanResults as getPersistedScans,
  getMonitorCycles,
  getGovernanceSnapshots,
  getDeploymentStats,
} from './deployment-persistence';
import {
  getRolloutController,
  getStageIndex,
} from './production-rollout-controller';
import {
  getAlertPipelineStatus,
  getAlertHistory,
  getAlertStats,
  getAlertRules,
  updateAlertRule,
  updateAlertPipelineConfig,
  sendManualAlert,
  startAlertingPipeline,
  stopAlertingPipeline,
  testSlackWebhook,
  getSlackStatus,
} from './admin-alerting-pipeline';
import {
  getMultiChannelNotifier,
} from './multi-channel-notifier';
import {
  saveRolloutState,
  loadRolloutState,
  recordRolloutEvent,
  getRolloutStateHistory,
  getRolloutEventHistory,
  getRolloutPersistenceStats,
  getActiveRolloutId,
} from './rollout-persistence';
import {
  autoRestoreRollout,
  getAutoRestoreConfig,
  updateAutoRestoreConfig,
  getAutoRestoreStatus,
} from './rollout-auto-restore';
import {
  compareRollouts,
  getComparableRollouts,
} from './rollout-comparison';
import {
  getNotificationPreferences,
} from './notification-preferences';
import {
  getRolloutScheduler,
} from './rollout-scheduler';
import {
  processReviewResult,
  getBridgeStats,
  getBridgeHistory,
  getLastBridgeResult,
  setBridgeEnabled,
  isBridgeEnabled,
} from './review-governance-bridge';
import {
  getReviewSchedulerStatus,
  getLastReviewResult,
  getReviewHistory,
  getReviewStats,
  getReviewConfig,
  updateReviewConfig,
  startAutonomousReview,
  stopAutonomousReview,
  runReviewCycle,
} from './autonomous-review-scheduler';
import {
  processFindings,
  getTasks,
  updateTaskStatus,
  getClosedLoopConfig,
  updateClosedLoopConfig,
  getClosedLoopStats,
  getDecisionHistory,
} from './closed-loop-actions';
import {
  startLoop,
  stopLoop,
  getLoopStatus,
  getLoopConfig,
  updateLoopConfig,
} from './autonomous-loop-orchestrator';

const adminGuard = protectedProcedure.use(({ ctx, next }) => {
  if (ctx.user.role !== 'admin') throw new TRPCError({ code: 'FORBIDDEN', message: 'Admin access required' });
  return next({ ctx });
});

export const deploymentRouter = router({
  // ─── Dashboard ────────────────────────────────────────────────────────
  getDashboardData: adminGuard.query(async () => {
    const deployer = getWebsiteContentDeployer();
    const bridge = getSelfImproveBridge();
    const scanner = getClosedLoopScanner();
    let gov;
    try { gov = await getGovernanceIntegration().takeSnapshot(); } catch { gov = null; }
    let dbStats;
    try { dbStats = await getDeploymentStats(); } catch { dbStats = null; }
    return {
      deployer: deployer.getStats(),
      bridge: bridge.getStatus(),
      scanner: scanner.getStats(),
      governance: gov,
      monitor: getMonitorStatus(),
      dbStats,
    };
  }),

  // ─── Governance ───────────────────────────────────────────────────────
  getGovernanceSnapshot: adminGuard.query(async () => getGovernanceIntegration().takeSnapshot()),
  getGovernanceScore: adminGuard.query(async () => {
    const s = await getGovernanceIntegration().getGovernanceScore();
    return { score: s, percent: `${(s * 100).toFixed(1)}%` };
  }),
  checkGovernanceRegression: adminGuard
    .input(z.object({ threshold: z.number().min(0).max(1).default(0.05) }))
    .query(async ({ input }) => getGovernanceIntegration().detectRegression(input.threshold)),
  refreshGovernanceCache: adminGuard.mutation(async () => {
    const gi = getGovernanceIntegration();
    gi.clearCache();
    const snap = await gi.takeSnapshot();
    return { success: true, score: snap.overallScore, status: snap.status };
  }),

  // ─── Deployer ─────────────────────────────────────────────────────────
  listDeployments: adminGuard
    .input(z.object({ limit: z.number().min(1).max(100).default(20) }))
    .query(({ input }) => getWebsiteContentDeployer().getDeploymentHistory(input.limit)),
  getDeployment: adminGuard
    .input(z.object({ id: z.string() }))
    .query(({ input }) => {
      const r = getWebsiteContentDeployer().getDeployment(input.id);
      if (!r) throw new TRPCError({ code: 'NOT_FOUND' });
      return r;
    }),
  rollbackDeployment: adminGuard
    .input(z.object({ deploymentId: z.string(), reason: z.string() }))
    .mutation(async ({ input }) => getWebsiteContentDeployer().rollback(input.deploymentId, input.reason)),
  getDeployerConfig: adminGuard.query(() => getWebsiteContentDeployer().getConfig()),
  updateDeployerConfig: adminGuard
    .input(z.object({
      maxConcurrent: z.number().min(1).max(5).optional(),
      requireGovernance: z.boolean().optional(),
      autoRollbackOnFailure: z.boolean().optional(),
      maxPatchesPerDeployment: z.number().min(1).max(50).optional(),
      dryRun: z.boolean().optional(),
    }))
    .mutation(({ input }) => { getWebsiteContentDeployer().updateConfig(input); return { success: true }; }),
  manualDeploy: adminGuard
    .input(z.object({
      patches: z.array(z.object({
        targetFile: z.string(),
        findText: z.string(),
        replaceText: z.string(),
        description: z.string(),
        category: z.enum(['headline', 'cta', 'proof', 'objection_handling', 'structure', 'tone', 'clarity', 'bug_fix', 'other']).default('other'),
      })),
      mode: z.enum(['staging', 'production']).default('staging'),
      reason: z.string(),
    }))
    .mutation(async ({ input }) => {
      try { await getClosedLoopScanner().capturePreDeploySnapshot(); } catch { /* non-critical */ }
      return getWebsiteContentDeployer().deploy({ patches: input.patches, mode: input.mode, source: 'manual', reason: input.reason });
    }),

  // ─── Bridge ───────────────────────────────────────────────────────────
  getBridgeEvents: adminGuard
    .input(z.object({ limit: z.number().min(1).max(100).default(20) }))
    .query(({ input }) => getSelfImproveBridge().getEvents(input.limit)),
  resetCircuitBreaker: adminGuard.mutation(() => { getSelfImproveBridge().resetCircuitBreaker(); return { success: true }; }),
  getBridgeConfig: adminGuard.query(() => getSelfImproveBridge().getConfig()),
  updateBridgeConfig: adminGuard
    .input(z.object({
      enabled: z.boolean().optional(),
      minConfidenceForPromotion: z.number().min(0).max(1).optional(),
      minImprovementDelta: z.number().min(0).max(1).optional(),
      circuitBreakerThreshold: z.number().min(1).max(20).optional(),
      rateLimitPerMinute: z.number().min(1).max(60).optional(),
    }))
    .mutation(({ input }) => { getSelfImproveBridge().updateConfig(input); return { success: true }; }),

  // ─── Scanner ──────────────────────────────────────────────────────────
  triggerScan: adminGuard
    .input(z.object({ deploymentId: z.string() }))
    .mutation(async ({ input }) => getClosedLoopScanner().scanDeployment(input.deploymentId)),
  capturePreDeploySnapshot: adminGuard.mutation(async () => {
    const s = await getClosedLoopScanner().capturePreDeploySnapshot();
    return { success: true, score: s.overallScore, status: s.status };
  }),
  getScanResults: adminGuard
    .input(z.object({ limit: z.number().min(1).max(100).default(20) }))
    .query(({ input }) => getClosedLoopScanner().getScanHistory(input.limit)),
  getScannerConfig: adminGuard.query(() => getClosedLoopScanner().getConfig()),
  updateScannerConfig: adminGuard
    .input(z.object({
      enabled: z.boolean().optional(),
      autoScanAfterDeploy: z.boolean().optional(),
      degradationThreshold: z.number().min(-1).max(0).optional(),
      autoRollbackOnDegradation: z.boolean().optional(),
      useRealGovernance: z.boolean().optional(),
    }))
    .mutation(({ input }) => { getClosedLoopScanner().updateConfig(input); return { success: true }; }),
  setBaseline: adminGuard
    .input(z.object({ metrics: z.record(z.string(), z.number()) }))
    .mutation(({ input }) => { getClosedLoopScanner().setBaseline(input.metrics); return { success: true }; }),

  // ─── Autonomous Monitor (Gap 1) ──────────────────────────────────────
  getMonitorStatus: adminGuard.query(() => getMonitorStatus()),
  getMonitorHistory: adminGuard
    .input(z.object({ limit: z.number().min(1).max(200).default(50) }))
    .query(({ input }) => getMonitorHistory(input.limit)),
  updateMonitorConfig: adminGuard
    .input(z.object({
      enabled: z.boolean().optional(),
      intervalMs: z.number().min(60000).max(86400000).optional(),
      maxPromotionsPerCycle: z.number().min(1).max(20).optional(),
      maxRollbacksPerCycle: z.number().min(1).max(20).optional(),
      enablePostDeployScans: z.boolean().optional(),
      dryRun: z.boolean().optional(),
    }))
