      if (!success) throw new TRPCError({ code: 'BAD_REQUEST', message: 'Cannot delete active or default profile' });
      return { success: true };
    }),
  updateQuietHours: adminGuard
    .input(z.object({
      profileId: z.string(),
      quietHours: z.object({
        enabled: z.boolean(),
        startHour: z.number().min(0).max(23),
        endHour: z.number().min(0).max(23),
        daysOfWeek: z.array(z.number().min(0).max(6)),
        bypassSeverity: z.enum(['info', 'warning', 'critical']),
      }),
    }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      const success = prefs.updateQuietHours(input.profileId, input.quietHours);
      if (!success) throw new TRPCError({ code: 'NOT_FOUND', message: 'Profile not found' });
      return { success: true };
    }),
  updateChannelPreference: adminGuard
    .input(z.object({
      profileId: z.string(),
      channelId: z.string(),
      minSeverity: z.enum(['info', 'warning', 'critical']).optional(),
      maxPerHour: z.number().min(1).max(1000).optional(),
      enabled: z.boolean().optional(),
      label: z.string().optional(),
    }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      const success = prefs.updateChannelPreference(input.profileId, input.channelId, input);
      if (!success) throw new TRPCError({ code: 'NOT_FOUND', message: 'Profile not found' });
      return { success: true };
    }),
  setGlobalNotificationsDisabled: adminGuard
    .input(z.object({ disabled: z.boolean() }))
    .mutation(async ({ input }) => {
      const prefs = getNotificationPreferences();
      prefs.setGlobalDisabled(input.disabled);
      return { success: true, disabled: input.disabled };
    }),
  getNotificationChangeLog: adminGuard.query(async () => {
    const prefs = getNotificationPreferences();
    return prefs.getChangeLog();
  }),

  // ─── Rollout Scheduling ─────────────────────────────────────────────
  createScheduledRollout: adminGuard.input(z.object({
    name: z.string(),
    description: z.string(),
    scheduledAt: z.number(),
    recurrence: z.enum(['once', 'daily', 'weekly', 'biweekly', 'monthly']).optional(),
    autoAdvance: z.boolean().optional(),
    maxDurationMs: z.number().optional(),
    tags: z.array(z.string()).optional(),
    preChecks: z.array(z.string()).optional(),
    rolloutConfigOverrides: z.object({
      shadowMode: z.boolean().optional(),
      logAllRequests: z.boolean().optional(),
      autoHealthChecks: z.boolean().optional(),
      errorRateThreshold: z.number().optional(),
      latencyThresholdMs: z.number().optional(),
    }).optional(),
  })).mutation(async ({ input, ctx }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.createSchedule({ ...input, createdBy: ctx.user.name || 'admin' });
  }),
  cancelScheduledRollout: adminGuard.input(z.object({
    id: z.string(),
    reason: z.string(),
  })).mutation(async ({ input, ctx }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.cancelSchedule(input.id, input.reason, ctx.user.name || 'admin');
  }),
  pauseScheduledRollout: adminGuard.input(z.object({ id: z.string() })).mutation(async ({ input, ctx }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.pauseSchedule(input.id, ctx.user.name || 'admin');
  }),
  resumeScheduledRollout: adminGuard.input(z.object({ id: z.string() })).mutation(async ({ input, ctx }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.resumeSchedule(input.id, ctx.user.name || 'admin');
  }),
  rescheduleRollout: adminGuard.input(z.object({
    id: z.string(),
    newTime: z.number(),
  })).mutation(async ({ input, ctx }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.reschedule(input.id, input.newTime, ctx.user.name || 'admin');
  }),
  getScheduledRollout: adminGuard.input(z.object({ id: z.string() })).query(async ({ input }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.getSchedule(input.id);
  }),
  listScheduledRollouts: adminGuard.input(z.object({
    status: z.enum(['pending', 'active', 'completed', 'cancelled', 'failed', 'paused']).optional(),
    limit: z.number().optional(),
  }).optional()).query(async ({ input }) => {
    const scheduler = getRolloutScheduler();
    return scheduler.listSchedules(input || {});
  }),
  getUpcomingRollouts: adminGuard.query(async () => {
    const scheduler = getRolloutScheduler();
    return scheduler.getUpcoming();
  }),
  getRolloutScheduleHistory: adminGuard.query(async () => {
    const scheduler = getRolloutScheduler();
    return scheduler.getHistory();
  }),
  getRolloutScheduleStats: adminGuard.query(async () => {
    const scheduler = getRolloutScheduler();
    return scheduler.getStats();
  }),
  getAvailablePreChecks: adminGuard.query(async () => {
    const scheduler = getRolloutScheduler();
    return scheduler.getAvailablePreChecks();
  }),

  // ─── Autonomous Review Scheduler ──────────────────────────────────────
  getReviewSchedulerStatus: adminGuard.query(async () => {
    return getReviewSchedulerStatus();
  }),
  getLastReviewResult: adminGuard.query(async () => {
    return getLastReviewResult();
  }),
  getReviewHistory: adminGuard.input(z.object({ limit: z.number().optional() }).optional()).query(async ({ input }) => {
    return getReviewHistory(input?.limit);
  }),
  getReviewStats: adminGuard.query(async () => {
    return getReviewStats();
  }),
  getReviewConfig: adminGuard.query(async () => {
    return getReviewConfig();
  }),
  updateReviewConfig: adminGuard.input(z.object({
    enabled: z.boolean().optional(),
    intervalMs: z.number().optional(),
    reviewDepth: z.enum(['quick', 'standard', 'deep']).optional(),
    maxFindingsPerReview: z.number().optional(),
    autoRemediationEnabled: z.boolean().optional(),
    quietHoursEnabled: z.boolean().optional(),
    quietHoursStart: z.number().optional(),
    quietHoursEnd: z.number().optional(),
  })).mutation(async ({ input }) => {
    return updateReviewConfig(input);
  }),
  startAutonomousReview: adminGuard.mutation(async () => {
    startAutonomousReview();
    return { success: true, message: 'Autonomous review started' };
  }),
  stopAutonomousReview: adminGuard.mutation(async () => {
    stopAutonomousReview();
    return { success: true, message: 'Autonomous review stopped' };
  }),
  triggerReviewCycle: adminGuard.mutation(async () => {
    const result = await runReviewCycle();
    return result;
  }),

  // ─── Review-Governance Bridge ─────────────────────────────────────────
  getBridgeStats: adminGuard.query(async () => {
    return getBridgeStats();
  }),
  getBridgeHistory: adminGuard.input(z.object({ limit: z.number().optional() }).optional()).query(async ({ input }) => {
    return getBridgeHistory(input?.limit);
  }),
  getLastBridgeResult: adminGuard.query(async () => {
    return getLastBridgeResult();
  }),
  setBridgeEnabled: adminGuard.input(z.object({ enabled: z.boolean() })).mutation(async ({ input }) => {
    setBridgeEnabled(input.enabled);
    return { success: true, enabled: input.enabled };
  }),
  isBridgeEnabled: adminGuard.query(async () => {
    return { enabled: isBridgeEnabled() };
  }),

  // ─── Closed-Loop Action System ─────────────────────────────────────────
  getClosedLoopStats: adminGuard.query(async () => {
    return getClosedLoopStats();
  }),
  getClosedLoopConfig: adminGuard.query(async () => {
    return getClosedLoopConfig();
  }),
  updateClosedLoopConfig: adminGuard.input(z.object({
    enabled: z.boolean().optional(),
    dryRun: z.boolean().optional(),
    autoRemediateEnabled: z.boolean().optional(),
    pauseOnCritical: z.boolean().optional(),
    rollbackOnSafety: z.boolean().optional(),
    createTasksForWarnings: z.boolean().optional(),
    escalateOnMultipleCritical: z.boolean().optional(),
    criticalThreshold: z.number().optional(),
    confidenceThreshold: z.number().optional(),
    maxAutoRemediationsPerCycle: z.number().optional(),
    cooldownMs: z.number().optional(),
  })).mutation(async ({ input }) => {
    return updateClosedLoopConfig(input);
  }),
  getDecisionHistory: adminGuard.input(z.object({ limit: z.number().optional() }).optional()).query(async ({ input }) => {
    return getDecisionHistory(input?.limit);
  }),
  getRemediationTasks: adminGuard.input(z.object({ status: z.enum(['pending', 'in_progress', 'completed', 'dismissed']).optional() }).optional()).query(async ({ input }) => {
    return getTasks(input?.status);
  }),
  updateTaskStatus: adminGuard.input(z.object({
    taskId: z.string(),
    status: z.enum(['pending', 'in_progress', 'completed', 'dismissed']),
    assignedTo: z.string().optional(),
  })).mutation(async ({ input }) => {
    const task = updateTaskStatus(input.taskId, input.status, input.assignedTo);
    if (!task) throw new TRPCError({ code: 'NOT_FOUND', message: 'Task not found' });
    return task;
  }),

  // ─── Autonomous Loop Orchestrator ─────────────────────────────────────
  getLoopStatus: adminGuard.query(async () => {
    return getLoopStatus();
  }),
  getLoopConfig: adminGuard.query(async () => {
    return getLoopConfig();
  }),
  updateLoopConfig: adminGuard.input(z.object({
    autoStartOnBoot: z.boolean().optional(),
    startDelayMs: z.number().optional(),
    enableBridge: z.boolean().optional(),
    enableClosedLoop: z.boolean().optional(),
  })).mutation(async ({ input }) => {
    return updateLoopConfig(input);
  }),
  startLoop: adminGuard.mutation(async () => {
    startLoop();
    return { success: true, status: getLoopStatus() };
  }),
  stopLoop: adminGuard.mutation(async () => {
    stopLoop();
    return { success: true, status: getLoopStatus() };
  }),
});

