// ─── Rollout Persistence ──────────────────────────────────────────────
saveRolloutSnapshot: adminGuard.mutation(async () => {
  const ctrl = getRolloutController();
  const state = ctrl.getState();
  const config = ctrl.getConfig();
  const healthHistory = ctrl.getHealthHistory(HEALTH_HISTORY_LIMIT);
  const id = await saveRolloutState({
    status: state.status,
    currentStage: getStageIndex(state.currentStage),
    percentage: state.rolloutPercentage,
    shadowMode: config.shadowMode,
    logAllRequests: config.logAllRequests,
    totalRequests: state.totalRequests,
    newVersionRequests: state.rolledOutRequests,
    healthChecksPassed: healthHistory.filter(h => h.passed).length,
    healthChecksFailed: healthHistory.filter(h => !h.passed).length,
    consecutiveFailures: state.consecutiveHealthFailures,
    config,
    startedAt: state.startedAt,
    completedAt: state.completedAt,
  });
  return { success: true, rolloutId: id };
}),

